def _get_trust_anchor_snapshot(self, tenant: str, query: str) -> None:
    # GET /v1/trust/anchors/snapshot?signer_did=：对本租户全部
    # 信任锚点生成签名快照。查询参数仅允许唯一非空 signer_did，
    # 缺失/空值/重复/未知参数一律 400 且仅 {"error"}；签名 DID
    # 未知（含他租户）404、已停用 409。200 键序 anchors、
    # signer_did、signer_key_version、signature；anchors 原子
    # 取本租户锚点并按 did 码点、key_version 升序，项键序 did、
    # key_version、public_key、status、updated_at、uses（类型
    # 沿用既有锚点与用途响应）；signature 由签名 DID 当前私钥
    # 对前三键递归键升序紧凑 UTF-8 JSON 做 ES256 裸 R||S 无填
    # 充 base64url 签名。纯只读：不写状态、不记审计。
    params = parse_qs(query, keep_blank_values=True)
    unknown = sorted(set(params) - {"signer_did"})
    if unknown:
        raise ValidationError(
            f"不支持的查询参数: {', '.join(unknown)}"
        )
    signer_values = params.get("signer_did")
    if signer_values is None:
        raise ValidationError("查询参数 signer_did 必填")
    if len(signer_values) != 1:
        raise ValidationError("查询参数 signer_did 只能提供一次")
    signer_did = signer_values[0]
    if not signer_did:
        raise ValidationError(
            "查询参数 signer_did 必须为非空字符串"
        )

    key_version, private_pem = (
        store.get_trust_anchor_snapshot_signer(tenant, signer_did)
    )
    anchors = store.list_trust_anchor_snapshot(tenant)
    signed = {
        "anchors": anchors,
        "signer_did": signer_did,
        "signer_key_version": key_version,
    }
    signature = crypto.sign(signed, private_pem)
    snapshot = dict(signed)
    snapshot["signature"] = signature
    self._send_json(200, snapshot)

def _anchor_snapshot_is_well_formed(self, snapshot: Any) -> bool:
    # 快照结构校验（“快照非法”）：恰含四键且各键类型/取值合法。
    if not isinstance(snapshot, dict):
        return False
    if set(snapshot) != {
        "anchors",
        "signer_did",
        "signer_key_version",
        "signature",
    }:
        return False
    anchors = snapshot["anchors"]
    if not isinstance(anchors, list):
        return False
    for item in anchors:
        if not isinstance(item, dict):
            return False
        if set(item) != {
            "did",
            "key_version",
            "public_key",
            "status",
            "updated_at",
            "uses",
        }:
            return False
        if not isinstance(item["did"], str) or not item["did"]:
            return False
        key_version = item["key_version"]
        if (
            not isinstance(key_version, int)
            or isinstance(key_version, bool)
            or key_version < 1
        ):
            return False
        if (
            not isinstance(item["public_key"], str)
            or not item["public_key"]
        ):
            return False
        if item["status"] not in ("active", "revoked"):
            return False
        updated_at = item["updated_at"]
        if updated_at is not None and not isinstance(
            updated_at, str
        ):
            return False
        uses = item["uses"]
        if not isinstance(uses, list) or not uses:
            return False
        if any(
            not isinstance(use, str) or use not in TRUST_ANCHOR_USES
            for use in uses
        ):
            return False
        if len(set(uses)) != len(uses) or list(uses) != sorted(
            uses, key=TRUST_ANCHOR_USES.index
        ):
            return False
    signer_did = snapshot["signer_did"]
    if not isinstance(signer_did, str) or not signer_did:
        return False
    signer_key_version = snapshot["signer_key_version"]
    if (
        not isinstance(signer_key_version, int)
        or isinstance(signer_key_version, bool)
        or signer_key_version < 1
    ):
        return False
    signature = snapshot["signature"]
    if not isinstance(signature, str) or not signature:
        return False
    return True

def _verify_anchor_snapshot_item(
    self, tenant: str, snapshot: Any
) -> Optional[str]:
    # 快照验真：按序返回失败原因（快照非法 -> 锚点不可用 ->
    # 签名格式错误 -> 签名校验失败），成功返回 None。纯只读。
    # 阶段一：快照键集/类型
    if not self._anchor_snapshot_is_well_formed(snapshot):
        return "快照非法"

    anchors = snapshot["anchors"]
    # 阶段二：anchors 按 did 码点、key_version 严格升序（无重复）
    keys = [(item["did"], item["key_version"]) for item in anchors]
    if any(
        keys[index] >= keys[index + 1]
        for index in range(len(keys) - 1)
    ):
        return "快照非法"

    signer_did = snapshot["signer_did"]
    signer_key_version = snapshot["signer_key_version"]

    # 阶段三：本租户同 signer_did/版本且含 generic 用途的
    # active 信任锚点
    public_pem = store.get_active_trust_anchor_public_key(
        tenant,
        signer_did,
        signer_key_version,
        required_use="generic",
    )
    if public_pem is None:
        return "锚点不可用"
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return "锚点不可用"

    signed = {
        "anchors": anchors,
        "signer_did": signer_did,
        "signer_key_version": signer_key_version,
    }
    signature = snapshot["signature"]

    # 阶段四：签名格式
    try:
        crypto.validate_signature_format_strict(signature)
    except crypto.MalformedSignature:
        return "签名格式错误"

    # 阶段五：密码学验签
    try:
        crypto.verify(signed, signature, public_pem)
    except crypto.MalformedSignature:
        return "签名格式错误"
    except crypto.InvalidSignature:
        return "签名校验失败"
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露细节
        return "签名校验失败"
    return None

def _post_trust_anchor_snapshot_verify(self, tenant: str) -> None:
    # POST /v1/trust/anchors/snapshot/verify：校验锚点快照签名。
    # 请求体须恰为 {"snapshot": 对象}，否则 400 且仅 {"error"}。
    # 外层合法后任何失败均 HTTP 200，按顺序返回
    # {"valid":false,"reason":...}：快照非法（键集/类型、anchors
    # 顺序/重复）-> 锚点不可用（本租户同 signer_did/版本且含
    # generic 用途的 active 锚点）-> 签名格式错误 -> 签名校验
    # 失败。成功仅 {"valid":true}。纯只读、租户隔离、不记审计。
    data = self._read_json()
    if set(data) != {"snapshot"}:
        if "snapshot" not in data:
            raise ValidationError("请求缺少字段: snapshot")
        extra = sorted(set(data) - {"snapshot"})
        raise ValidationError(
            f"请求含多余字段: {', '.join(extra)}"
        )
    snapshot = data["snapshot"]
    if not isinstance(snapshot, dict):
        raise ValidationError(
            "请求不合法: 字段 snapshot 必须为 JSON 对象"
        )
    reason = self._verify_anchor_snapshot_item(tenant, snapshot)
    if reason is not None:
        self._send_json(200, {"valid": False, "reason": reason})

"""ES256 签名与规范化 JSON。

ES256 即 ECDSA over P-256 与 SHA-256。签名以 JWS 约定编码：
64 字节裸 R||S 的 base64url（无填充）。cryptography 库签出的是 DER，
这里在 DER 与 R||S 之间做转换。
"""

import base64
import json
import re
from typing import Any, Dict

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric.utils import (
    decode_dss_signature,
    encode_dss_signature,
)

__all__ = [
    "InvalidSignature",
    "MalformedSignature",
    "canonicalize",
    "generate_private_key_pem",
    "public_key_pem_from_private",
    "validate_public_key_pem",
    "validate_signature_format",
    "validate_signature_format_strict",
    "sign",
    "verify",
]


class MalformedSignature(ValueError):
    """签名编码格式非法（无法解码或不是 64 字节裸 R||S）。"""


def _b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64url_decode(text: str) -> bytes:
    padding = "=" * (-len(text) % 4)
    return base64.urlsafe_b64decode(text + padding)


def canonicalize(body: Dict[str, Any]) -> bytes:
    """正文按 key 升序的规范化 JSON 序列化（紧凑、UTF-8 字节）。"""
    return json.dumps(
        body, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def generate_private_key_pem() -> str:
    """生成 P-256 私钥，返回 PKCS8 PEM 字符串。"""
    private_key = ec.generate_private_key(ec.SECP256R1())
    pem = private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption(),
    )
    return pem.decode("utf-8")


def public_key_pem_from_private(private_pem: str) -> str:
    """从私钥 PEM 导出对应的 SubjectPublicKeyInfo 公钥 PEM。"""
    private_key = serialization.load_pem_private_key(
        private_pem.encode("utf-8"), password=None
    )
    if not isinstance(private_key, ec.EllipticCurvePrivateKey):
        raise ValueError("私钥不是 P-256 椭圆曲线私钥")
    if not isinstance(private_key.curve, ec.SECP256R1):
        raise ValueError("私钥曲线不是 P-256")
    pem = private_key.public_key().public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo,
    )
    return pem.decode("utf-8")


def _load_public_key(public_pem: str) -> ec.EllipticCurvePublicKey:
    try:
        key = serialization.load_pem_public_key(public_pem.encode("utf-8"))
    except (ValueError, TypeError) as exc:
        raise ValueError(f"公钥 PEM 无法解析: {exc}") from exc
    if not isinstance(key, ec.EllipticCurvePublicKey) or not isinstance(
        key.curve, ec.SECP256R1
    ):
        raise ValueError("公钥不是 P-256 椭圆曲线公钥")
    return key


def validate_public_key_pem(public_pem: str) -> None:
    """校验公钥 PEM 可解析且为 ES256 所需的 P-256 公钥，否则抛 ValueError。"""
    _load_public_key(public_pem)


def _load_private_key(private_pem: str) -> ec.EllipticCurvePrivateKey:
    try:
        key = serialization.load_pem_private_key(
            private_pem.encode("utf-8"), password=None
        )
    except (ValueError, TypeError) as exc:
        raise ValueError(f"私钥 PEM 无法解析: {exc}") from exc
    if not isinstance(key, ec.EllipticCurvePrivateKey) or not isinstance(
        key.curve, ec.SECP256R1
    ):
        raise ValueError("私钥不是 P-256 椭圆曲线私钥")
    return key


def sign(body: Dict[str, Any], private_pem: str) -> str:
    """对规范化正文做 ES256 签名，返回 base64url(R||S)。"""
    private_key = _load_private_key(private_pem)
    der = private_key.sign(
        canonicalize(body), ec.ECDSA(hashes.SHA256())
    )
    r, s = decode_dss_signature(der)
    raw = r.to_bytes(32, "big") + s.to_bytes(32, "big")
    return _b64url(raw)


def validate_signature_format(signature_b64: str) -> None:
    """校验签名编码格式：须为可解码的 base64url 且裸 R||S 恰为 64 字节。

    仅检查格式，不做密码学验签。格式非法抛 MalformedSignature。
    """
    try:
        raw = _b64url_decode(signature_b64)
    except Exception as exc:  # noqa: BLE001 解码异常（含 binascii）均属格式问题
        raise MalformedSignature("签名不是合法的 base64url 编码") from exc
    if len(raw) != 64:
        raise MalformedSignature("签名长度不是 64 字节，非合法 ES256 签名")


# 严格格式：64 字节裸 R||S 的无填充 base64url 恰为 86 个字符
_RAW_RS_B64URL_STRICT_RE = re.compile(r"[A-Za-z0-9_-]{86}")


def validate_signature_format_strict(signature_b64: str) -> None:
    """严格校验签名编码格式：恰为 86 个 base64url 字符（无填充、无字
    母表外字符），解码恰为 64 字节裸 R||S，且无填充 base64url 重编码
    与原文逐字符一致（排除填充与非规范尾位）。

    仅检查格式，不做密码学验签。格式非法抛 MalformedSignature。
    """
    if not isinstance(signature_b64, str) or not (
        _RAW_RS_B64URL_STRICT_RE.fullmatch(signature_b64)
    ):
        raise MalformedSignature(
            "签名不是 86 字符的无填充 base64url 编码"
        )
    raw = _b64url_decode(signature_b64)
    if len(raw) != 64 or _b64url(raw) != signature_b64:
        raise MalformedSignature(
            "签名不是规范的 64 字节裸 R||S 无填充 base64url 编码"
        )


def verify(body: Dict[str, Any], signature_b64: str, public_pem: str) -> None:
    """校验签名：格式非法抛 MalformedSignature，验签失败抛 InvalidSignature。"""
    validate_signature_format(signature_b64)
    public_key = _load_public_key(public_pem)
    raw = _b64url_decode(signature_b64)
    r = int.from_bytes(raw[:32], "big")
    s = int.from_bytes(raw[32:], "big")
    der = encode_dss_signature(r, s)
    public_key.verify(der, canonicalize(body), ec.ECDSA(hashes.SHA256()))

