def expect_valid(name, proof_obj, headers=None):
    st, raw = proof_post({"proof": proof_obj}, headers=headers)
    try:
        body = json.loads(raw)
    except ValueError:
        body = None
    check(name, st == 200 and body == {"valid": True})

